#include <iostream>
using namespace std;

// Queue implementation using Linked List
struct Node {
    int data;
    Node* next;
    Node(int x) : data(x), next(nullptr) {}
};

class Queue {
    Node *frontNode, *rearNode;
    int sz;
public:
    Queue() : frontNode(nullptr), rearNode(nullptr), sz(0) {}

    void enqueue(int x) {
        Node* newNode = new Node(x);
        if (!rearNode) { frontNode = rearNode = newNode; }
        else { rearNode->next = newNode; rearNode = newNode; }
        sz++;
    }

    int dequeue() {
        if (!frontNode) { cout << "Underflow\n"; return -1; }
        int val = frontNode->data;
        Node* temp = frontNode;
        frontNode = frontNode->next;
        if (!frontNode) rearNode = nullptr;
        delete temp;
        sz--;
        return val;
    }

    int front() { return frontNode ? frontNode->data : -1; }
    int rear() { return rearNode ? rearNode->data : -1; }
    bool isEmpty() { return frontNode == nullptr; }
    int size() { return sz; }
};

int main() {
    Queue q;
    q.enqueue(10); q.enqueue(20); q.enqueue(30);
    cout << "Front: " << q.front() << endl;  // 10
    cout << "Rear: " << q.rear() << endl;    // 30
    q.dequeue();
    cout << "Front after dequeue: " << q.front() << endl;  // 20
    cout << "isEmpty: " << q.isEmpty() << endl;  // 0
    return 0;
}

