#include <iostream>
using namespace std;

class CircularQueue {
    int *arr;
    int front, rear, capacity;
public:
    CircularQueue(int cap) : capacity(cap), front(-1), rear(-1) {
        arr = new int[cap];
    }

    bool enqueue(int x) {
        if ((rear + 1) % capacity == front) {
            cout << "Queue is Full" << endl;
            return false;
        }
        if (front == -1) front = 0;
        rear = (rear + 1) % capacity;
        arr[rear] = x;
        return true;
    }

    int dequeue() {
        if (front == -1) {
            cout << "Queue is Empty" << endl;
            return -1;
        }
        int val = arr[front];
        if (front == rear) { front = rear = -1; }  // last element
        else { front = (front + 1) % capacity; }
        return val;
    }

    int getFront() { return front == -1 ? -1 : arr[front]; }
    int getRear() { return rear == -1 ? -1 : arr[rear]; }
    bool isEmpty() { return front == -1; }
    bool isFull() { return (rear + 1) % capacity == front; }
};

int main() {
    CircularQueue cq(5);
    cq.enqueue(10); cq.enqueue(20); cq.enqueue(30); cq.enqueue(40);
    cout << "Front: " << cq.getFront() << endl;  // 10
    cq.dequeue(); cq.dequeue();
    cq.enqueue(50); cq.enqueue(60);  // wraps around!
    cout << "Front: " << cq.getFront() << endl;  // 30
    return 0;
}

