#include <stdio.h>
#define MAX 100

// Simple Min Priority Queue using array
int pq[MAX], pqSize = 0;

void pqPush(int x) {
    pq[pqSize++] = x;
    // Bubble up
    int i = pqSize - 1;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (pq[parent] <= pq[i]) break;
        int temp = pq[parent]; pq[parent] = pq[i]; pq[i] = temp;
        i = parent;
    }
}

int pqTop() { return pqSize > 0 ? pq[0] : -1; }

// Deque using array
int dq[MAX], dqFront = MAX/2, dqRear = MAX/2 - 1;
void pushBack(int x) { dq[++dqRear] = x; }
void pushFront(int x) { dq[--dqFront] = x; }
int popFront() { return dq[dqFront++]; }
int popBack() { return dq[dqRear--]; }

int main() {
    pqPush(30); pqPush(10); pqPush(20);
    printf("Min PQ top: %d\n", pqTop());  // 10

    pushBack(10); pushFront(20); pushBack(30);
    printf("Deque front: %d\n", dq[dqFront]);  // 20
    return 0;
}
